	// data type to string column
	private static class DataTypeColumn : AbstractProgramLocationTableColumn<ProgramLocation, string> {

		/* @Override */
		public string getColumnName() {
			return "Data Type";
		}

		/* @Override */
		public string getValue(ProgramLocation rowObject, Settings settings, Program program,
				ServiceProvider serviceProvider)
    {
			Data data = DataUtilities.getDataAtLocation(rowObject);
			if (data == null) {
				return "";
			}
			return (data.getDataType() is AbstractStringDataType)
					? data.getDataType().getMnemonic(settings)
					: data.getDataType().getName();
		}

		/* @Override */
		public ProgramLocation getProgramLocation(ProgramLocation rowObject, Settings settings,
				Program program, ServiceProvider serviceProvider) {
			return rowObject;
		}

	}

	private static class IsAsciiColumn : AbstractProgramLocationTableColumn<ProgramLocation, Boolean> {

		/* @Override */
		public string getColumnName() {
			return "Is Ascii";
		}

		/* @Override */
		public Boolean getValue(ProgramLocation rowObject, Settings settings, Program program,
				ServiceProvider serviceProvider)
    {

			Data data = DataUtilities.getDataAtLocation(rowObject);
			string s = StringDataInstance.getStringDataInstance(data).getStringValue();

			return (s != null) &&
				s.codePoints().allMatch(codePoint => 0 <= codePoint && codePoint < 0x80);
		}

		/* @Override */
		public ProgramLocation getProgramLocation(ProgramLocation rowObject, Settings settings,
				Program program, ServiceProvider serviceProvider) {
			return rowObject;
		}

	}

	private static class HasEncodingErrorColumn : AbstractProgramLocationTableColumn<ProgramLocation, Boolean> {

		/* @Override */
		public string getColumnName() {
			return "Has Encoding Error";
		}

		/* @Override */
		public Boolean getValue(ProgramLocation rowObject, Settings settings, Program program,
				ServiceProvider serviceProvider)
    {

			Data data = DataUtilities.getDataAtLocation(rowObject);
			string s = StringDataInstance.getStringDataInstance(data).getStringValue();

			return (s != null) && s.codePoints()
					.anyMatch(codePoint => codePoint == StringUtilities.UNICODE_REPLACEMENT);
		}

		/* @Override */
		public ProgramLocation getProgramLocation(ProgramLocation rowObject, Settings settings,
				Program program, ServiceProvider serviceProvider) {
			return rowObject;
		}

	}

